    public static TheoryData<string> HighVarianceBesideLowVarianceBlockCases => new(s_highVarianceBesideLowVarianceBlock.Keys);

    public static TheoryData<string> VerifiableOptimumCases => new(s_verifiableOptima.Keys);

    [Theory]
    [MemberData(nameof(HighVarianceBesideLowVarianceBlockCases))]
    public void QpMinVariance_DecimalHighVarianceAssetBesideLowVarianceBlock_ReturnsTheExactOptimum(string caseId)
    {
        AssertExactOptimum(s_highVarianceBesideLowVarianceBlock[caseId], caseId);
    }

    [Theory]
    [MemberData(nameof(VerifiableOptimumCases))]
    public void QpMinVariance_DecimalVerifiableOptimum_IsReturnedNotRefused(string caseId)
    {
        AssertExactOptimum(s_verifiableOptima[caseId], caseId);
    }

    [Fact]
    public void QpMinVariance_DecimalOptimalWeightBelowWeightResolution_ReturnsTheExactOptimum()
    {
        // w0* = 1e-24 / (13/12 + 1e-24) ≈ 9.231e-25 has four significant digits in decimal, and one unit of its
        // last digit moves the high-variance row's gradient by 1e-16 against a row of 1e-12, so no
        // decimal vector meets a 1e-10 relative bound measured without the weights' resolution.
        decimal[,] covariance =
        {
            { 1000000000000m, 0m, 0m, 0m },
            { 0m, 0.000000000002m, 0m, 0m },
            { 0m, 0m, 0.000000000003m, 0m },
            { 0m, 0m, 0m, 0.000000000004m },
        };

        var weights = Solve(() => ActiveSetQpSolver<decimal>.SolveMinVariance(covariance, 0m, 1m), "hd-diag4-12");

        // Exact optimum w_i ∝ 1/Σ_ii: (1e-24, 1/2, 1/3, 1/4) / (13/12 + 1e-24).
        decimal[] optimum =
        [
            0.0000000000000000000000009231m, 0.461538461538461538461538036m,
            0.307692307692307692307692024m, 0.230769230769230769230769018m,
        ];
        AssertWeights(weights, optimum, 1e-12m, "hd-diag4-12");
    }

    // A fixed, well-conditioned 5×5 covariance. Minimum-variance weights are invariant under Σ → s·Σ,
    // and mean-variance weights under (Σ, μ, λ) → (s·Σ, m·μ, λ·m/s), so the optimum at every scale is
    // the exact optimum of the unit-scale problem.
    private static readonly decimal[,] s_unitCovariance =
    {
        { 4.0m, 1.2m, 0.6m, 0.3m, 0.1m },
        { 1.2m, 3.0m, 0.9m, 0.2m, 0.4m },
        { 0.6m, 0.9m, 2.5m, 0.7m, 0.3m },
        { 0.3m, 0.2m, 0.7m, 1.8m, 0.5m },
        { 0.1m, 0.4m, 0.3m, 0.5m, 1.2m },
    };

    public static TheoryData<string> SmallCovarianceScales => new() { "0.000000000000000001", "0.0000000000000000001", "0.00000000000000000001" };

    [Theory]
    [MemberData(nameof(SmallCovarianceScales))]
    public void QpMinVariance_DecimalCovarianceOfOrder1e18OrBelow_ReturnsTheScaleFreeOptimum(string scale)
    {
        // Entries of order 1e-18 times weights of order 0.1 give products of order 1e-19, which keep
        // only nine digits on decimal's absolute 1e-28 grid if they are formed unscaled.
        var covariance = Scaled(s_unitCovariance, Parse(scale));

        var weights = Solve(() => ActiveSetQpSolver<decimal>.SolveMinVariance(covariance, 0m, 1m), "Σ·" + scale);

        decimal[] optimum =
        [
            0.113485721243639320244391506m, 0.0899676540654342348428757441m, 0.124682088757872906204645481m,
            0.207864363107173648766749872m, 0.464000172825879889941337397m,
        ];
        AssertWeights(weights, optimum, 1e-12m, "Σ·" + scale);
    }

    [Fact]
    public void QpMeanVariance_DecimalCovarianceOfOrder1e18WithRiskAversion1e14_ReturnsTheScaleFreeOptimum()
    {
        // (Σ·1e-18, μ·1e-4, λ = 1e14) is the scale-free problem (Σ, μ·1e-4, λ·1e-18 = 1e-4).
        var covariance = Scaled(s_unitCovariance, 0.000000000000000001m);
        decimal[] means = [0.000008m, 0.000005m, 0.000011m, 0.000003m, 0.000006m];

        var weights = Solve(
            () => ActiveSetQpSolver<decimal>.SolveMeanVariance(covariance, means, 100000000000000m, 0m, 1m),
            "mean-variance Σ·1e-18");

        decimal[] optimum =
        [
            0.120062924331723565005116039m, 0.0752199111125076838778985159m, 0.155599460311911434592278218m,
            0.176587003101046185752470134m, 0.472530701142811130772237094m,
        ];
        AssertWeights(weights, optimum, 1e-12m, "mean-variance Σ·1e-18");
    }

    [Fact]
    public void KktCertificate_DecimalLowVarianceRowsBesideHighVarianceRow_RejectsAVectorWrongInTheLowVarianceRows()
    {
        // high-variance-37. Row 0 (variance 4e12) has magnitude ~1.6e-5; rows 1-4 (variance 1.5e-12) have ~7.5e-13.
        // The vector below was returned by the pre-rewrite verification patch: right in row 0, but rows 1-4 are
        // off by 1.5e-4 relative, 127 times the optimal variance. Measured against the largest row it passed;
        // measured against each row's own scale it fails. (Re-pinned at the release of the rewrite: the pre-rewrite
        // residual type this test called was deleted with the old core; the independent KKT certificate that
        // replaced it is the unit under test, at the nominal tolerance scale.)
        var testCase = s_highVarianceBesideLowVarianceBlock["high-variance-37"];
        var covariance = testCase.CovarianceMatrix;
        decimal[] wrong =
        [
            -0.0000000000000000019649370682m, 0.2499875006249686962121577656m, 0.2499875006249687m,
            0.2499875006249687978174126968m, 0.2500374981250938079353666058m,
        ];
        var lower = Parse(testCase.Lower);
        var upper = Parse(testCase.Upper);

        Boutquin.Numerics.Internal.QpKktCertificate<decimal>.Check(covariance, null, 1m, lower, upper, testCase.OptimumVector).Accepted
            .Should().BeTrue("the exact optimum rounded to decimal must be certified");
        Boutquin.Numerics.Internal.QpKktCertificate<decimal>.Check(covariance, null, 1m, lower, upper, wrong).Accepted
            .Should().BeFalse("a vector 1.5e-4 off in the low-variance rows must be rejected");
    }

    [Fact]
    public void QpMeanVariance_DecimalWeightsOfOrder1e4_ReturnsTheExactOptimum()
    {
        // budget-mean-5: |w| up to 7009, so the budget magnitude 1 + Σ|w| is 1.4e4. The ratio
        // of each residual to its allowance must be formed without overflowing decimal.
        decimal[,] covariance =
        {
            { 40000000000m, 0m, 0m },
            { 0m, 0.000000000200000000000008m, -0.000000000199999999999992m },
            { 0m, -0.000000000199999999999992m, 0.000000000200000000000008m },
        };
        decimal[] means = [41562.3m, 61364.3m, -7.68707m];

        var weights = Solve(
            () => ActiveSetQpSolver<decimal>.SolveMeanVariance(covariance, means, 0.00000006m, -7000m, 90000000m),
            "budget-mean-5");

        // Exact optimum: asset 2 at the lower bound; one-unit input sensitivity 2.0e-24.
        decimal[] optimum = [-8.25083333333333326328707917m, 7009.25083333333333326328708m, -7000m];
        AssertWeights(weights, optimum, 1e-12m * 7009.25m, "budget-mean-5");
    }

    private static decimal[,] Scaled(decimal[,] matrix, decimal scale)
    {
        var n = matrix.GetLength(0);
        var result = new decimal[n, n];
        for (var i = 0; i < n; i++)
        {
            for (var j = 0; j < n; j++)
            {
                result[i, j] = matrix[i, j] * scale;
            }
        }

        return result;
    }

    private static void AssertExactOptimum(MinVarianceCase testCase, string caseId)
    {
        var weights = Solve(
            () => ActiveSetQpSolver<decimal>.SolveMinVariance(
                testCase.CovarianceMatrix, Parse(testCase.Lower), Parse(testCase.Upper)),
            caseId);

        AssertWeights(weights, testCase.OptimumVector, Parse(testCase.Tolerance), caseId);
    }

    private static decimal[] Solve(Func<decimal[]> solve, string caseId) =>
        solve.Should().NotThrow("{0} has a representable, verifiable optimum inside the box", caseId).Subject;

    private static void AssertWeights(decimal[] weights, decimal[] optimum, decimal tolerance, string caseId)
    {
        // The documented budget check: relative error at most max(k·√ε, 1e-10) = 1e-10 for decimal.
        var magnitude = 1m + weights.Sum(Math.Abs);
        Math.Abs(weights.Sum() - 1m).Should().BeLessThanOrEqualTo(
            1e-10m * magnitude, "the documented postcondition of {0} is an optimal weight vector summing to 1", caseId);
        for (var i = 0; i < optimum.Length; i++)
        {
            weights[i].Should().BeApproximately(
                optimum[i], tolerance, "weight {0} of {1} must be the exact KKT optimum", i, caseId);
        }
    }

    private static decimal Parse(string value) => decimal.Parse(value, NumberStyles.Float, s_invariant);

    private sealed record MinVarianceCase(string[][] Covariance, string Lower, string Upper, string[] Optimum, string Tolerance)
    {
        public decimal[,] CovarianceMatrix
        {
            get
            {
                var n = Covariance.Length;
                var matrix = new decimal[n, n];
                for (var i = 0; i < n; i++)
                {
                    for (var j = 0; j < n; j++)
                    {
                        matrix[i, j] = Parse(Covariance[i][j]);
                    }
                }

                return matrix;
            }
        }

        public decimal[] OptimumVector => Optimum.Select(Parse).ToArray();
    }
}
